    27	
    28	/// 屏幕宽度（像素）。
    29	pub const SCREEN_W: usize = 160;
    30	/// 屏幕高度（像素）。
    31	pub const SCREEN_H: usize = 144;
    32	/// 一帧的像素数；帧缓冲每字节一个像素，取值只有 0xFF/0xAA/0x55/0x00（色号 0 = 0xFF）。
    33	pub const FRAME_PIXELS: usize = SCREEN_W * SCREEN_H;
    34	/// 一帧的 T-cycle 数（154 行 × 456 dot）。`Machine::run_frame` 与 LCD 开关无关地按它推进。
    35	pub const FRAME_T: u32 = 70224;
    36	
    37	/// 一帧画面：160×144，行优先。
    38	pub type Frame = [u8; FRAME_PIXELS];
    39	
    40	/// 中断位（IF/IE 的 bit 序号与掩码）。`CpuBus::ack` 接收的是 bit 序号 0..=4。
    41	pub mod irq {
    42	    pub const VBLANK: u8 = 1 << 0;
    43	    pub const STAT: u8 = 1 << 1;
    44	    pub const TIMER: u8 = 1 << 2;
    45	    pub const SERIAL: u8 = 1 << 3;
    46	    pub const JOYPAD: u8 = 1 << 4;
    47	}
    48	
    49	/// `Machine::set_buttons` 的位定义：1 = 按下。
    50	pub mod buttons {
    51	    pub const A: u8 = 1 << 0;
    52	    pub const B: u8 = 1 << 1;
    53	    pub const SELECT: u8 = 1 << 2;
    54	    pub const START: u8 = 1 << 3;
    55	    pub const RIGHT: u8 = 1 << 4;
    56	    pub const LEFT: u8 = 1 << 5;
    57	    pub const UP: u8 = 1 << 6;
    58	    pub const DOWN: u8 = 1 << 7;
    59	}
    60	
    61	/// 外设统一形态（timer/serial/joypad/ppu 都遵守；DMA 另有接口，见 `dma.rs`）。
    62	///
    63	/// Bus 每个 M-cycle 依次调用 timer → serial → joypad → ppu 的 `tick_mcycle`，再推进 DMA，
    64	/// 并把返回的中断位或进 IF。`read_reg` 必须无副作用（`Machine::peek` 也走它）。
    65	pub trait Peripheral: Snapshot {
    66	    /// 推进 1 个 M-cycle（4 T），返回本周期新请求的中断位（IF 位掩码，见 `irq`）。
    67	    fn tick_mcycle(&mut self) -> u8;
    68	    /// 读 I/O 寄存器，`addr` 为绝对地址（如 0xFF04）。
    69	    fn read_reg(&self, addr: u16) -> u8;
    70	    /// 写 I/O 寄存器，`addr` 为绝对地址。
    71	    fn write_reg(&mut self, addr: u16, v: u8);
    72	}
