     1	//! SM83 CPU（core 通道，T10/T11/T14）。
     2	//!
     3	//! 冻结部分（D001）：`CpuBus` trait、`Cpu` 的公开字段、`Cpu::new`、`Cpu::step`、`Snapshot for Cpu`。
     4	//! 内部状态（EI 延迟、HALT bug、锁死等）由 core 自行增加私有或公开字段；增加字段不算改签名。
     5	
     6	use crate::state::{Snapshot, StateError, StateReader, StateWriter};
     7	
     8	/// CPU 看到的总线。每次调用恰好消耗 1 个 M-cycle（`pending`/`ack` 除外，它们不耗时）。
     9	pub trait CpuBus {
    10	    /// 读一个字节：1 M-cycle。
    11	    fn read(&mut self, addr: u16) -> u8;
    12	    /// 写一个字节：1 M-cycle。
    13	    fn write(&mut self, addr: u16, v: u8);
    14	    /// 内部周期：1 M-cycle，无总线访问。
    15	    fn idle(&mut self);
    16	    /// `IE & IF & 0x1F`，不耗时。
    17	    fn pending(&self) -> u8;
    18	    /// 清除 IF 的第 `bit` 位（`bit` 为序号 0..=4，0 = VBlank），不耗时。
    19	    fn ack(&mut self, bit: u8);
    20	    /// 执行 STOP 时调用（不耗时）：Bus 借此清零 DIV。测试用的假总线可以不实现。
    21	    fn stop(&mut self) {}
    22	}
