     1	//! PPU（ppu 通道，T40–T42）：逐扫描线渲染加双缓冲（PLAN §3.5）。
     2	//!
     3	//! 冻结部分（D001）：`Ppu::new`、VRAM/OAM 访问方法、`dma_write_oam`、`frame`、`Peripheral` 实现
     4	//! （`tick_mcycle` 返回 VBlank/STAT 中断位；`read_reg`/`write_reg` 处理 FF40–FF45、FF47–FF4B；
     5	//! FF46 归 `dma.rs`）、`Snapshot`。VRAM 与 OAM 数组由本模块持有，Bus 只做转发。
     6	//!
     7	//! T02 空壳：存储与访问已可用，`tick_mcycle` 不推进时序（返回 0），由 T40 替换。
     8	//! 在此之前整机仍可运行（Blargg 的控制台在 LY 不变时会超时后继续）。
     9	
    10	use crate::state::{Snapshot, StateError, StateReader, StateWriter};
    11	use crate::{Frame, Peripheral, FRAME_PIXELS};
    12	
    13	pub struct Ppu {
    14	    vram: [u8; 0x2000],
    15	    oam: [u8; 0xA0],
    16	    /// 最近一个完整帧（进入 LY=144 时由后缓冲交换而来）。
    17	    front: Box<Frame>,
    18	    /// 正在绘制的帧。
    19	    back: Box<Frame>,
    20	    /// FF40–FF4B 的寄存器存储（T02 空壳用；T40 起可替换为具名字段）。
    21	    regs: [u8; 12],
    22	}
    23	
    24	impl Default for Ppu {
    25	    fn default() -> Self {
    26	        Self::new()
    27	    }
    28	}
    29	
    30	impl Ppu {
    31	    /// DMG 开机状态（Pan Docs Power_Up_Sequence 的硬件寄存器表，DMG 列），前缓冲为全白。
    32	    pub fn new() -> Self {
    33	        let mut regs = [0u8; 12];
    34	        regs[0x0] = 0x91; // LCDC
    35	        regs[0x1] = 0x85; // STAT
    36	        regs[0x7] = 0xFC; // BGP
    37	        Self {
    38	            vram: [0; 0x2000],
    39	            oam: [0; 0xA0],
    40	            front: Box::new([0xFF; FRAME_PIXELS]),
    41	            back: Box::new([0xFF; FRAME_PIXELS]),
    42	            regs,
    43	        }
    44	    }
    45	
    46	    /// CPU 读 VRAM，`addr` 为绝对地址 0x8000..=0x9FFF。无副作用（`peek` 也走这里）。
    47	    pub fn read_vram(&self, addr: u16) -> u8 {
    48	        self.vram[(addr & 0x1FFF) as usize]
    49	    }
    50	
    51	    /// CPU 写 VRAM，`addr` 为绝对地址 0x8000..=0x9FFF。
    52	    pub fn write_vram(&mut self, addr: u16, v: u8) {
    53	        self.vram[(addr & 0x1FFF) as usize] = v;
    54	    }
    55	
    56	    /// CPU 读 OAM，`addr` 为绝对地址 0xFE00..=0xFE9F。无副作用。
    57	    pub fn read_oam(&self, addr: u16) -> u8 {
    58	        self.oam[(addr as usize - 0xFE00) % 0xA0]
    59	    }
    60	
    61	    /// CPU 写 OAM，`addr` 为绝对地址 0xFE00..=0xFE9F。
    62	    pub fn write_oam(&mut self, addr: u16, v: u8) {
    63	        self.oam[(addr as usize - 0xFE00) % 0xA0] = v;
    64	    }
    65	
    66	    /// OAM DMA 写入第 `index`（0..160）个字节；由 Bus 驱动，不受 PPU 模式封锁影响。
    67	    pub fn dma_write_oam(&mut self, index: u8, v: u8) {
    68	        self.oam[index as usize % 0xA0] = v;
    69	    }
    70	
    71	    /// 最近一个完整帧（前缓冲），值为 0xFF/0xAA/0x55/0x00。
    72	    pub fn frame(&self) -> &Frame {
    73	        &self.front
    74	    }
    75	}
