    77	impl Peripheral for Ppu {
    78	    fn tick_mcycle(&mut self) -> u8 {
    79	        // T02 空壳：T40 实现 dot 计数、LY、mode、STAT、VBlank 与双缓冲交换。
    80	        let _ = &mut self.back;
    81	        0
    82	    }
