    26	            StateError::BadMagic => write!(f, "not a gbemu save state"),
    27	            StateError::BadVersion(v) => write!(f, "unsupported save state version {v}"),
    28	            StateError::RomMismatch => write!(f, "save state belongs to a different ROM"),
    29	            StateError::Corrupt(what) => write!(f, "corrupt save state: {what}"),
