}

#[test]
fn load_state_rejects_bad_magic() {
    let mut m = machine();
    assert_eq!(m.load_state(b""), Err(StateError::BadMagic));
    assert_eq!(m.load_state(b"GBEM"), Err(StateError::BadMagic));
