        if first_timer.is_none() && b.pending() & irq::TIMER != 0 {
            first_timer = Some(n);
        }
    }
    let n = first_timer.expect("timer interrupt while idling");
    assert!((60..=70).contains(&n), "timer IRQ after {n} M-cycles");
    assert_eq!(b.pending(), irq::TIMER | irq::SERIAL);
