use crate::serial::Serial;
use crate::state::{Snapshot, StateError, StateReader, StateWriter};
use crate::timer::Timer;
use crate::{Frame, Peripheral};

/// APU 寄存器与波形 RAM（FF10–FF3F）的字节数。
const APU_LEN: usize = 0x30;

/// APU 区（FF10–FF3F）的开机值（Power_Up_Sequence 的 DMG 列；表中未列出的地址与未使用的地址读 0xFF）。
/// 波形 RAM（FF30–FF3F）开机内容不确定，取 0x00。
fn apu_power_up() -> [u8; APU_LEN] {
    let mut apu = [0xFF; APU_LEN];
    let table: [(u16, u8); 21] = [
        (0xFF10, 0x80), // NR10
        (0xFF11, 0xBF), // NR11
        (0xFF12, 0xF3), // NR12
        (0xFF13, 0xFF), // NR13
        (0xFF14, 0xBF), // NR14
        (0xFF16, 0x3F), // NR21
        (0xFF17, 0x00), // NR22
        (0xFF18, 0xFF), // NR23
        (0xFF19, 0xBF), // NR24
        (0xFF1A, 0x7F), // NR30
        (0xFF1B, 0xFF), // NR31
        (0xFF1C, 0x9F), // NR32
        (0xFF1D, 0xFF), // NR33
        (0xFF1E, 0xBF), // NR34
        (0xFF20, 0xFF), // NR41
        (0xFF21, 0x00), // NR42
        (0xFF22, 0x00), // NR43
        (0xFF23, 0xBF), // NR44
        (0xFF24, 0x77), // NR50
        (0xFF25, 0xF3), // NR51
        (0xFF26, 0xF1), // NR52
    ];
    for (addr, v) in table {
        apu[(addr - 0xFF10) as usize] = v;
    }
    for b in &mut apu[0x20..] {
        *b = 0x00;
    }
    apu
}

pub struct Bus {
    pub(crate) cart: Box<dyn Cart>,
    pub(crate) wram: Box<[u8; 0x2000]>,
    pub(crate) hram: [u8; 0x7F],
    /// FF10–FF3F：APU 寄存器只做可读写存储（不发声，PLAN §1.1）。
    pub(crate) apu: [u8; APU_LEN],
    pub(crate) ints: Interrupts,
    pub(crate) timer: Timer,
    pub(crate) serial: Serial,
    pub(crate) joypad: Joypad,
    pub(crate) ppu: Ppu,
    pub(crate) dma: Dma,
    /// 开机以来的 M-cycle 数。
    pub(crate) mcycles: u64,
}

impl Bus {
    /// DMG 开机状态（不执行 boot ROM，Power_Up_Sequence 的 DMG 列）。各外设在自己的 `new` 中给出开机值
    /// （P1=CF、SB=00、SC=7E、DIV=AB、TIMA=00、TMA=00、TAC=F8、IF=E1、IE=00；PPU 寄存器在 `Ppu::new`）。
    pub fn new(cart: Box<dyn Cart>) -> Self {
        Self {
            cart,
            wram: Box::new([0; 0x2000]),
            hram: [0; 0x7F],
            apu: apu_power_up(),
            ints: Interrupts::new(),
            timer: Timer::new(),
            serial: Serial::new(),
            joypad: Joypad::new(),
            ppu: Ppu::new(),
            dma: Dma::new(),
            mcycles: 0,
        }
    }

    pub fn mcycles(&self) -> u64 {

