            0xFF40..=0xFF45 | 0xFF47..=0xFF4B => self.ppu.write_reg(addr, v),'''
new='''            0xFF26 => {
                // bit7 可写；bit3–0 只读，关闭 APU 时清零。
                let status = if v & 0x80 != 0 { self.apu[NR52] & 0x0F } else { 0 };
