                    self.bits_left = 0;
                }
            }
            _ => {}
        }
    }
}

impl Snapshot for Serial {
    fn save(&self, w: &mut StateWriter) {
        w.tag(b"SERI");
        w.u8(self.sb);
        w.u8(self.sc);
        w.u8(self.bits_left);
        w.u16(self.counter);
        w.u16(self.last_counter);
    }

    fn load(&mut self, r: &mut StateReader) -> Result<(), StateError> {
        r.tag(b"SERI")?;
        let sb = r.u8()?;
        let sc = r.u8()?;
        let bits_left = r.u8()?;
        let counter = r.u16()?;
        let last_counter = r.u16()?;
