use gb_core::{CpuBus, Peripheral, Snapshot, StateReader, StateWriter};

const SB: u16 = 0xFF01;
const SC: u16 = 0xFF02;

fn ticks(s: &mut Serial, n: u32) -> u8 {
    (0..n).fold(0, |acc, _| acc | s.tick_mcycle())
}

