/// 执行 1 条指令，或 1 次中断分派，或 HALT/锁死状态下的 1 个 M-cycle。
/// 每次调用至少消耗 1 个 M-cycle（至少调用一次 read/write/idle），绝不为 0。
pub fn step<B: CpuBus>(&mut self, bus: &mut B) {
    if self.locked {
        bus.idle();
        return;
    }
    if self.halted {
        if bus.pending() == 0 {
            // 外设由 bus 在这个 M-cycle 里照常推进。
            bus.idle();
            return;
        }
        // 有挂起中断即唤醒，不额外耗时：与用一串 NOP 等待中断的时序相同（Pan Docs halt.md）。
        self.halted = false;
    }
    if self.ime && bus.pending() != 0 {
        self.dispatch(bus);
        return;
    }
    let enable_ime = self.ei_pending;
    self.ei_pending = false;
    let op = self.fetch_opcode(bus);
    self.execute(bus, op);
    if enable_ime && op != OP_DI {
        self.ime = true;
    }
}

// ---- 16 位寄存器对 ----

#[inline(always)]
pub fn af(&self) -> u16 {
    u16::from_be_bytes([self.a, self.f])
}
#[inline(always)]
pub fn bc(&self) -> u16 {
    u16::from_be_bytes([self.b, self.c])
}
// ---- 总线辅助：每次 read/write/idle = 1 M-cycle ----

/// 取操作码；HALT bug 触发后的那一次不递增 PC。
#[inline(always)]
fn fetch_opcode<B: CpuBus>(&mut self, bus: &mut B) -> u8 {
    let op = bus.read(self.pc);
    if self.halt_bug {
        self.halt_bug = false;
    } else {
        self.pc = self.pc.wrapping_add(1);
    }
    op
}
#[inline(always)]
fn imm8<B: CpuBus>(&mut self, bus: &mut B) -> u8 {
    let v = bus.read(self.pc);
    self.pc = self.pc.wrapping_add(1);
    v
    self.set_flags(nf);
}

/// 中断分派：5 M-cycle。
fn dispatch<B: CpuBus>(&mut self, bus: &mut B) {
    self.ime = false;
    // 分派取代了"EI 之后的那条指令"，EI 的延迟生效随之作废，避免处理程序第一条指令后 IME 被重新打开。
    self.ei_pending = false;
    if self.halt_bug {
        // `EI; HALT` 且 HALT 时已有挂起中断：硬件上那次不递增 PC 的取指已经发生，分派又把 PC 回退 1，
        // 所以压栈的是 HALT 自身的地址，返回后 HALT 再执行一次（Pan Docs halt.md）。
        self.halt_bug = false;
        self.pc = self.pc.wrapping_sub(1);
    }
    bus.idle();
    bus.idle();
    let [hi, lo] = self.pc.to_be_bytes();
    self.sp = self.sp.wrapping_sub(1);
    bus.write(self.sp, hi);
    // 写完 PCH 之后才选择向量：这次写若改了 IE，可能取消分派（PC=0x0000）或换成别的中断。
    let pending = bus.pending();
    let vector = if pending == 0 {
        0x0000
