        let bit = pending.trailing_zeros() as u8;
        bus.ack(bit);
        0x0040 + 8 * bit as u16
    };
    self.sp = self.sp.wrapping_sub(1);
    bus.write(self.sp, lo);
    bus.idle();
    self.pc = vector;
}

